<?php
require_once __DIR__ . '/../public/db_connect.php';  $id = 'MERCH2026125350963';  echo "Checking Receipt Data for: $id\n";
echo str_repeat("=", 60) . "\n\n";  try {  // Check transaction  $stmt = $pdo->prepare("SELECT * FROM merchandise_transactions WHERE transaction_id = ?");  $stmt->execute([$id]);  $txn = $stmt->fetch(PDO::FETCH_ASSOC);  if ($txn) {  echo " Transaction Found:\n";  echo "  ID: {$txn['id']}\n";  echo "  Transaction ID: {$txn['transaction_id']}\n";  echo "  Customer: {$txn['customer_name']}\n";  echo "  Staff ID: {$txn['staff_id']}\n";  echo "  Transaction Type: {$txn['transaction_type']}\n";  echo "  Job Order Service: " . ($txn['job_order_service'] ?? 'NULL') . "\n";  echo "  JO Vehicle Plate: " . ($txn['job_order_vehicle_plate'] ?? 'NULL') . "\n";  echo "  JO Mechanic: " . ($txn['job_order_mechanic_name'] ?? 'NULL') . "\n";  echo "\n";  // Check staff  if ($txn['staff_id']) {  $stmt2 = $pdo->prepare("SELECT id, username FROM users WHERE id = ?");  $stmt2->execute([$txn['staff_id']]);  $staff = $stmt2->fetch(PDO::FETCH_ASSOC);  if ($staff) {  echo " Staff Found:\n";  echo "  ID: {$staff['id']}\n";  echo "  Username: " . ($staff['username'] ?? 'NULL') . "\n";  } else {  echo " Staff NOT found for ID: {$txn['staff_id']}\n";  }  }  echo "\n";  // Check items  $stmt3 = $pdo->prepare("SELECT * FROM merchandise_transaction_items WHERE transaction_id = ?");  $stmt3->execute([$txn['id']]);  $items = $stmt3->fetchAll(PDO::FETCH_ASSOC);  echo "Items: " . count($items) . "\n";  if (count($items) > 0) {  foreach ($items as $item) {  echo "  - {$item['product_name']} (Qty: {$item['quantity']}, Type: {$item['item_type']}, Price: ₱{$item['subtotal']})\n";  }  } else {  echo "  NO ITEMS FOUND!\n";  }  } else {  echo " Transaction NOT found\n";  }  } catch (Exception $e) {  echo "ERROR: " . $e->getMessage() . "\n";
}
?>
